package nl.smartstreamlabs.sbwdroneconfig;

import com.mojang.blaze3d.vertex.*;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.core.Direction;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import org.joml.Vector3f;import software.bernie.geckolib.cache.object.*;import java.util.*;import java.io.*;

/** Three resident passes: exterior, interior and light lenses. Individual structural groups can disappear. */

public final class Pb01Model{

 private static Pb01Model cached;private final GeoCube[]cubes;private final BakedGeoModel[]models=new BakedGeoModel[3];private final ResourceLocation texture=ResourceLocation.tryParse("sbwdroneconfig:pb01/pb01.png");public static Pb01Model get(){if(cached==null)cached=new Pb01Model();return cached;}public static void clear(){if(cached!=null)for(var m:cached.models)Adv01Gpu.release(m);cached=null;}

 private Pb01Model(){var g=Pb01Geometry.MODEL;cubes=new GeoCube[g.parts.size()];List<GeoBone>[]groups=new List[]{new ArrayList<>(),new ArrayList<>(),new ArrayList<>()};try(var in=new DataInputStream(Minecraft.getInstance().getResourceManager().getResourceOrThrow(ResourceLocation.tryParse("sbwdroneconfig:pb01/pb01.bin")).open())){if(in.readInt()!=0x44454631||in.readInt()!=cubes.length)throw new IOException("PB01 mesh header");for(int n=0;n<cubes.length;n++){int count=in.readInt();if(count<0||count>50000)throw new IOException("PB01 mesh length");var faces=new GeoQuad[count];for(int f=0;f<count;f++){var normal=new Vector3f(in.readFloat(),in.readFloat(),in.readFloat());var vertices=new GeoVertex[4];for(int k=0;k<4;k++)vertices[k]=new GeoVertex(in.readFloat(),in.readFloat(),in.readFloat()).withUVs(in.readFloat(),in.readFloat());faces[f]=new GeoQuad(vertices,normal,Direction.getNearest(normal.x,normal.y,normal.z));}cubes[n]=new GeoCube(faces,Vec3.ZERO,Vec3.ZERO,new Vec3(1,1,1),0,false);MeshRenderData.register(cubes[n]);var b=new GeoBone(null,g.bones.get(g.parts.get(n).bone()).name(),false,0d,false,false);b.getCubes().add(cubes[n]);groups[g.parts.get(n).category()].add(b);}if(in.read()!=-1)throw new IOException("PB01 trailing geometry");}catch(IOException e){throw new IllegalStateException("Cannot load complete PB01 model",e);}for(int i=0;i<3;i++)models[i]=new BakedGeoModel(groups[i],null);}

 public void draw(PoseStack p,MultiBufferSource buffers,int outside,int inside,int overlay,float progress,int mask,boolean lights,boolean preview,boolean valid){var g=Pb01Geometry.MODEL;var type=preview?RenderType.entityTranslucent(texture):RenderType.entityCutoutNoCull(texture);float red=preview?(valid?.45f:1):1,green=preview?(valid?1:.2f):1,blue=preview?(valid?.65f:.2f):1,alpha=preview?.32f:1;for(int cat=0;cat<3;cat++){int light=cat==0?outside:cat==2&&lights?0xf000f0:inside;var batch=buffers instanceof MultiBufferSource.BufferSource?Adv01Gpu.batch(models[cat]):null;if(batch!=null)batch.begin();for(int i=0;i<cubes.length;i++){var part=g.parts.get(i);if(part.category()!=cat)continue;boolean visible=(mask&(1<<part.zone()))!=0;if(!visible&&batch==null)continue;p.pushPose();var matrix=visible?g.pose(part.bone(),progress):new org.joml.Matrix4f().scaling(0f);p.last().pose().mul(matrix);if(visible)p.last().normal().mul(new org.joml.Matrix3f(matrix));if(batch!=null)batch.pose(cubes[i],p);else emit(p,buffers.getBuffer(type),MeshRenderData.get(cubes[i]),light,overlay,red,green,blue,alpha);p.popPose();}if(batch!=null)batch.draw(type,light,overlay,red,green,blue,alpha);}}

 private static void emit(PoseStack poses,VertexConsumer consumer,MeshRenderData data,int light,int overlay,float red,float green,float blue,float alpha){var m=poses.last().pose();var n=poses.last().normal();var v=data.values;for(int at=0;at<v.length;at+=23){float a=v[at],b=v[at+1],c=v[at+2];float nx=n.m00()*a+n.m10()*b+n.m20()*c,ny=n.m01()*a+n.m11()*b+n.m21()*c,nz=n.m02()*a+n.m12()*b+n.m22()*c;for(int i=at+3;i<at+23;i+=5){float x=v[i],y=v[i+1],z=v[i+2];float px=m.m00()*x+m.m10()*y+m.m20()*z+m.m30(),py=m.m01()*x+m.m11()*y+m.m21()*z+m.m31(),pz=m.m02()*x+m.m12()*y+m.m22()*z+m.m32();consumer.addVertex(px,py,pz,net.minecraft.util.FastColor.ARGB32.color((int)(alpha*255),(int)(red*255),(int)(green*255),(int)(blue*255)),v[i+3],v[i+4],overlay,light,nx,ny,nz);}}}

}

